async function api(path, body) {
  const response = await fetch('/api' + path, body === undefined ? {} : { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
  const data = await response.json()
  if (!response.ok) throw new Error(data.error || 'Request failed')
  return data
}
const label = value => String(value || '').replaceAll('_', ' ')
const clock = value => `${Math.floor((value || 0) / 60).toString().padStart(2,'0')}:${Math.floor((value || 0) % 60).toString().padStart(2,'0')}`
const formatBytes = value => value>=1024**3?`${(value/1024**3).toFixed(1)} GB`:value>=1024**2?`${(value/1024**2).toFixed(1)} MB`:value>=1024?`${(value/1024).toFixed(1)} KB`:`${value||0} B`
const media = (id, path) => `/api/runs/${id}/media?path=${encodeURIComponent(path)}`
const nav = [{id:'materials', name:'Materials', icon:FolderOpen}, {id:'panels',name:'Panel review',icon:ImageIcon}, {id:'ranges',name:'Correspondence',icon:Link2}, {id:'matches',name:'Matching workspace',icon:ScanLine}, {id:'results',name:'Assessment',icon:Grid2X2}, {id:'provenance',name:'Provenance',icon:ShieldCheck}]

function Field({label: title, children, hint}) { return <label className="field"><span>{title}</span>{children}{hint && <small>{hint}</small>}</label> }
function StateBadge({value}) { const good=['provisionally_matched','human_confirmed','completed'].includes(value); return <Badge variant="outline" className={good?'status-good':'status-neutral'}><CircleDot size={11}/>{label(value || 'not run')}</Badge> }
function Explain({children, text}) { return <Tooltip><TooltipTrigger asChild><span tabIndex={0} className="explain-label" aria-label={typeof children==='string'?children:undefined}>{children}<Info size={13} aria-hidden="true"/></span></TooltipTrigger><TooltipContent className="max-w-sm whitespace-normal">{text}</TooltipContent></Tooltip> }

const metricHelp = {
  'Supported Final frames':'Unique retained Final frames with at least one selected Storyboard or Animatic match. A frame supported by both routes counts once. Includes provisional automatic selections and human corrections.',
  'Visual support':'Supported Final frames / all retained sampled Final frames × 100. Unmatched frames lower this score. This measures coverage of selected evidence, not visual similarity or verified matching accuracy.',
  'Sequence consistency':'Across eligible routes, concordant comparisons / (concordant + discordant comparisons) × 100. All pairs of selected matches are compared in Final order. Ties are excluded. A route needs at least three selected matches and one non-tied comparison. Routes are weighted by comparable-pair counts, not averaged equally.',
  'Relationship':'The matching route: Final → Storyboard or Final → Animatic. Each route is evaluated separately.',
  'Route':'The evidence type compared with Final. A Final frame can contribute one evaluation per route.',
  'Selected pairs':'Number of selected Final–evidence matches on this route, including automatic selections and human corrections.',
  'Concordant':'For two matches in increasing Final order, the later match has a larger evidence index. All combinations are checked, not only adjacent frames.',
  'Discordant':'For two matches in increasing Final order, the later match has a smaller evidence index. These inversions reduce sequence consistency; they can also arise from matching errors.',
  'Ties':'Two Final frames select the same evidence index. These comparisons are excluded from the sequence-score denominator.',
  'Score':'Concordant / (concordant + discordant) × 100. N/A means fewer than three selected matches or no non-tied comparisons.',
  'Conformance score':'Conforming Final–route evaluations / all declared Final–route evaluations × 100. Outside-baseline selections and missing selections reduce the score. Undeclared intervals are excluded. Correspondence is checked after global retrieval.',
  'Evaluable Final routes':'Number of Final-frame/route evaluations covered by a correspondence declaration. One Final frame covered on both routes contributes two evaluations.',
  'Conforming pairs':'Selected matches whose evidence index belongs to the declared evidence set for that Final timestamp.',
  'Conforming':'Conforming evaluations / evaluations with a declared baseline on this route.',
  'Outside baseline':'A selected evidence index falls outside the set declared for this Final timestamp. This is disagreement with the declaration, not proof of an incorrect match.',
  'Expected not observed':'A declared baseline covers the Final frame, but no evidence match was selected. This remains in the conformance denominator.',
  'Undeclared':'No correspondence declaration covers the Final timestamp on this route. Excluded from the conformance score.',
  'Expected evidence coverage':'Unique declared evidence indices selected anywhere on this route / all unique declared evidence indices × 100. A selection at the wrong Final time still counts here; inspect conformance separately.',
  'Check':'An individual provenance rubric condition. Hover over each check for the extracted evidence and explanation.',
  'Satisfied':'Whether this applicable rubric condition passed. Missing or failed evidence earns zero points; non-applicable checks are excluded from the denominator.',
  'Points':'Points awarded / maximum points for this check. Indicator score = total awarded / total applicable maximum × 100, subject to any displayed gate.',
}
function MetricLabel({children}) { return <Explain text={metricHelp[children]}>{children}</Explain> }
function assessmentReason(title, scores) {
  if(!scores) return 'No assessment is available yet. Run matching to calculate this metric.'
  if(title==='Sequence consistency') {
    const routes=(scores.route_order||[]).filter(r=>r.score!=null)
    const concordant=routes.reduce((n,r)=>n+r.concordant_pair_count,0)
    const comparable=routes.reduce((n,r)=>n+r.comparable_pair_count,0)
    return `${metricHelp[title]} Current result: ${concordant} / ${comparable} × 100 = ${scores.sequence_consistency_score??'N/A'}%.`
  }
  return `${metricHelp[title]} Current result: ${scores.supported_final_frames} supported frames out of ${scores.total_final_frames} retained samples${title==='Visual support'?` × 100 = ${scores.visual_support_score??'N/A'}%`:''}.`
}
function sequenceReason(r) { return r.score==null?'N/A: at least three selected matches and one non-tied comparison are required.':`${r.concordant_pair_count} / (${r.concordant_pair_count} + ${r.discordant_pair_count}) × 100 = ${r.score}%. ${r.tied_pair_count} tied comparisons excluded.` }
function provenanceReason(s) { return `${s.points_awarded} / ${s.maximum_points} applicable points × 100 = ${s.score??'N/A'}. ${s.reason||''} ${s.gate_reason||''} ${(s.components||[]).map(c=>`${label(c.check)}: ${c.applicable?`${c.points_awarded}/${c.maximum_points} points`:'not applicable'}`).join('; ')}` }

function PanelReview({run, manifest, setManifest, locked, onSave}) {
  const [pageIndex,setPageIndex]=useState(1)
  if(!manifest) return <Card className="empty-state"><ImageIcon size={40}/><h2>No Storyboard submitted</h2><p>Panel review is available when the evidence includes a Storyboard PDF.</p></Card>
  const page=manifest.pages.find(item=>item.page_index===pageIndex)||manifest.pages[0]
  const updatePage=next=>setManifest({...manifest,pages:manifest.pages.map(item=>item.page_index===page.page_index?next:item)})
  const updateCandidate=(index,patch)=>updatePage({...page,candidates:page.candidates.map((item,i)=>i===index?{...item,...patch}:item)})
  const addCandidate=()=>{const [x0,y0,x1,y1]=page.content_bbox||[0,0,...page.size];const inset=Math.round(Math.min(x1-x0,y1-y0)*.05);updatePage({...page,candidates:[...page.candidates,{bbox:[x0+inset,y0+inset,x1-inset,y1-inset],method:'manual_review',decision:'accept',order:page.candidates.length+1}]})}
  const accepted=manifest.pages.reduce((total,item)=>total+item.candidates.filter(candidate=>candidate.decision==='accept').length,0)
  return <>
    <div className="summary-strip"><span><FileText size={16}/><strong>{manifest.pages.length}</strong> PDF pages</span><span><ImageIcon size={16}/><strong>{accepted}</strong> panels selected</span><Badge variant={run.prepared.panel_review_confirmed?'default':'secondary'} className="ml-auto">{run.prepared.panel_review_confirmed?'Review confirmed':'Confirmation required'}</Badge></div>
    <div className="panel-review-layout"><Card className="panel-page-card"><CardHeader className="flex flex-row items-center justify-between"><CardTitle className="text-base">Page {page.page_index}</CardTitle><Select value={String(page.page_index)} onValueChange={value=>setPageIndex(Number(value))}><SelectTrigger className="page-select"><SelectValue/></SelectTrigger><SelectContent>{manifest.pages.map(item=><SelectItem key={item.page_index} value={String(item.page_index)}>Page {item.page_index}</SelectItem>)}</SelectContent></Select></CardHeader><CardContent><div className="panel-page-preview"><img src={media(run.id,page.page_path)} alt={`Storyboard page ${page.page_index}`}/><svg viewBox={`0 0 ${page.size[0]} ${page.size[1]}`} aria-label="Panel candidate boundaries">{page.candidates.map((candidate,index)=><g key={index}><rect className={candidate.decision==='accept'?'accepted-box':'rejected-box'} x={candidate.bbox[0]} y={candidate.bbox[1]} width={candidate.bbox[2]-candidate.bbox[0]} height={candidate.bbox[3]-candidate.bbox[1]}/><text x={candidate.bbox[0]+8} y={candidate.bbox[1]+24}>{candidate.order??index+1}</text></g>)}</svg></div><p className="subtext mt-4">Green boxes will be exported as panels. Grey boxes are excluded. Coordinates use the rendered PDF page shown above.</p></CardContent></Card>
      <Card><CardHeader className="flex flex-row items-center justify-between"><div><CardTitle className="text-base">Candidate boundaries</CardTitle><p className="subtext mt-1">Review every page before matching.</p></div><Button variant="outline" size="sm" onClick={addCandidate} disabled={locked}><Plus size={14}/>Add box</Button></CardHeader><CardContent><div className="panel-candidate-list">{page.candidates.length===0&&<div className="empty-inline"><ImageIcon size={26}/><p>No candidate boxes on this page</p><small>Add a box manually, or leave the page empty.</small></div>}{page.candidates.map((candidate,index)=><div className={candidate.decision==='accept'?'panel-candidate-row accepted':'panel-candidate-row'} key={index}><div className="candidate-row-heading"><strong>Box {index+1}</strong><div className="decision-buttons"><Button size="sm" variant={candidate.decision==='accept'?'default':'outline'} onClick={()=>updateCandidate(index,{decision:'accept'})} disabled={locked}>Keep</Button><Button size="sm" variant={candidate.decision==='reject'?'secondary':'ghost'} onClick={()=>updateCandidate(index,{decision:'reject'})} disabled={locked}>Exclude</Button><button aria-label={`Delete box ${index+1}`} onClick={()=>updatePage({...page,candidates:page.candidates.filter((_,i)=>i!==index)})} disabled={locked}><X size={14}/></button></div></div><div className="panel-coordinate-grid"><Field label="Order"><Input type="number" min="1" value={candidate.order??index+1} onChange={event=>updateCandidate(index,{order:Number(event.target.value)})}/></Field>{['Left','Top','Right','Bottom'].map((name,coordinate)=><Field key={name} label={name}><Input type="number" min="0" value={candidate.bbox[coordinate]} onChange={event=>{const bbox=[...candidate.bbox];bbox[coordinate]=Number(event.target.value);updateCandidate(index,{bbox})}}/></Field>)}</div><small>{label(candidate.method)}</small></div>)}</div><div className="panel-review-actions"><span>Selected panels are re-cropped and their text descriptions are re-extracted after confirmation.</span><Button disabled={locked||accepted===0} onClick={()=>onSave(manifest.pages)}>Confirm panel extraction<ArrowRight size={14}/></Button></div></CardContent></Card></div>
  </>
}

const timestampHelp = {
  score:'Final timestamp evidence score. It equals points earned for weighted availability and chronology, minus the capped proximity deduction. It is not an authenticity probability.',
  availability:'How much of the four weighted timestamp evidence types can be compared: embedded creation 35%, embedded modification 30%, filesystem creation 20%, filesystem modification 15%.',
  chronology:'Weighted consistency of comparable timestamps. Evidence before Final earns 100; up to 24 hours later earns 70; one to seven days later earns 25; more than seven days later earns 0.',
  proximity:'A maximum 15-point deduction for unusually close embedded creation or modification times. Filesystem-only proximity is reported but does not deduct points.',
  timestamp:'The timestamp evidence type being compared. Embedded values come from media metadata; filesystem values can change when a file is copied or downloaded.',
  weight:'The maximum share of timestamp evidence assigned to this field. A missing field reduces availability and therefore caps the final score.',
  evidence:'The timestamp extracted from the submitted Storyboard or Animatic.',
  final:'The corresponding timestamp extracted from the Final file.',
  itemScore:'The chronology score for this timestamp pair before availability weighting and proximity deductions.',
  result:'The interpretation of the individual comparison. It is a review signal, not a verdict about authenticity.',
}

function TimestampRelationshipCard({relationship: r, modern}) {
  if (!modern) return <Card className="mb-5"><CardHeader><CardTitle className="text-base capitalize">{label(r.relationship)} · legacy timestamp output</CardTitle></CardHeader><CardContent><div className="soft-note"><CircleHelp size={16}/><p>This saved run uses the previous timestamp schema. Select “Inspect provenance” to calculate weighted scores and explanations.</p></div><div className="table-wrap mt-4"><table><thead><tr><th>Timestamp</th><th>Evidence</th><th>Final</th><th>Result</th></tr></thead><tbody>{r.comparisons.map(c=><tr key={c.timestamp_type}><td>{label(c.timestamp_type)}</td><td>{c.evidence_value||'Unavailable'}</td><td>{c.final_value||'Unavailable'}</td><td>{label(c.status)}</td></tr>)}</tbody></table></div></CardContent></Card>
  const b=r.score_breakdown||{}
  const proximityFindings=r.temporal_proximity?.findings||[]
  const reportedWithoutDeduction=proximityFindings.filter(f=>(f.proposed_deduction||0)>0&&(f.deduction_applied||0)===0)
  const deductionExplanation=reportedWithoutDeduction.length
    ? 'Close timing was observed, but it is supported only by filesystem timestamps. Copying, upload, extraction or batch export can reset these values, so the system reports the signal without deducting points.'
    : r.proximity_deduction>0
      ? 'Points were deducted because unusually close timing is supported by embedded media timestamps. The total proximity deduction is capped at 15 points.'
      : 'No qualifying embedded timestamp proximity was found, so no close-timing points were deducted.'
  return <Card className="mb-5" key={r.relationship}><CardHeader><CardTitle className="text-base capitalize">{label(r.relationship)} · <Explain text={timestampHelp.score}>Timestamp score</Explain> <Explain text={`${b.base_points_earned??'N/A'} base points − ${b.proximity_points_deducted??0} proximity deduction = ${b.final_points??'N/A'}. ${r.reason||''}`}>{r.timestamp_score??'N/A'}{r.timestamp_score!=null&&'/100'}</Explain></CardTitle></CardHeader><CardContent>
    <div className="assessment-grid timestamp-metrics"><div><Explain text={timestampHelp.availability}>Availability</Explain><strong><Explain text={timestampHelp.availability}>{r.availability_score}%</Explain></strong></div><div><Explain text={timestampHelp.chronology}>Chronology</Explain><strong><Explain text={timestampHelp.chronology}>{r.chronology_consistency==null?'N/A':`${r.chronology_consistency}%`}</Explain></strong></div><div><Explain text={timestampHelp.proximity}>Proximity deduction</Explain><strong><Explain text={timestampHelp.proximity}>−{r.proximity_deduction}</Explain></strong></div></div>
    <p className="subtext mt-4">{r.reason}</p>
    <div className="score-explanation mt-4"><strong>Why this score</strong><div className="score-ledger"><span className="earned">+{b.availability_points_earned??0}<small>Availability points earned</small></span><span className="earned">+{b.chronology_points_earned??0}<small>Chronology points earned</small></span><span className="missed">−{b.points_not_earned_missing_timestamps??0}<small>Not earned: missing timestamps</small></span><span className="missed">−{b.points_not_earned_chronology??0}<small>Not earned: chronology</small></span><span className="deducted">−{b.proximity_points_deducted??0}<small><Explain text={deductionExplanation}>Deducted: close timing</Explain></small></span></div><p>{b.base_points_earned??'N/A'} base points − {b.proximity_points_deducted??0} proximity deduction = <strong>{b.final_points??'N/A'} final points</strong>.</p>{reportedWithoutDeduction.length>0&&<p className="deduction-note"><Info size={13}/><span><strong>Close timing reported without deduction.</strong> The signal comes only from filesystem timestamps, which may reflect copying, upload or batch export rather than creation.</span></p>}</div>
    <div className="table-wrap mt-4"><table><thead><tr><th><Explain text={timestampHelp.timestamp}>Timestamp</Explain></th><th><Explain text={timestampHelp.weight}>Weight</Explain></th><th><Explain text={timestampHelp.evidence}>Evidence</Explain></th><th><Explain text={timestampHelp.final}>Final</Explain></th><th><Explain text={timestampHelp.itemScore}>Score</Explain></th><th><Explain text={timestampHelp.result}>Result</Explain></th></tr></thead><tbody>{r.comparisons.map(c=><tr key={c.timestamp_type}><td><Explain text={c.reason}>{label(c.timestamp_type)}</Explain></td><td>{c.weight_percent}%</td><td>{c.evidence_value||'Unavailable'}</td><td>{c.final_value||'Unavailable'}</td><td><Explain text={`${timestampHelp.itemScore} ${c.reason||''}`}>{c.score==null?'N/A':c.score}</Explain></td><td><Explain text={c.reason}>{label(c.status)}</Explain></td></tr>)}</tbody></table></div>
    {r.temporal_proximity?.findings?.length>0&&<div className="soft-note mt-4"><CircleHelp size={16}/><div>{r.temporal_proximity.findings.map(f=><p key={f.check}><Explain text={f.reason}><strong>{label(f.status)}</strong></Explain> · {f.gap_hours} hours · {label(f.confidence)} confidence · deduction {f.deduction_applied}</p>)}</div></div>}
  </CardContent></Card>
}

function App() {
  const [boot,setBoot]=useState(null), [run,setRun]=useState(null), [page,setPage]=useState('matches')
  const [error,setError]=useState(''), [notice,setNotice]=useState(''), [job,setJob]=useState(null), [jobInfo,setJobInfo]=useState(null)
  const [busy,setBusy]=useState(false), [settingsOpen,setSettingsOpen]=useState(false), [cacheOpen,setCacheOpen]=useState(false)
  const [draft,setDraft]=useState(null), [policy,setPolicy]=useState('range_top1'), [useText,setUseText]=useState(true), [useStructure,setUseStructure]=useState(true), [topK,setTopK]=useState(5), [minimum,setMinimum]=useState(.25), [margin,setMargin]=useState(.02)
  const [panelManifest,setPanelManifest]=useState(null)
  const [first,setFirst]=useState(null), [last,setLast]=useState(null), [kind,setKind]=useState('storyboard'), [from,setFrom]=useState(0), [to,setTo]=useState(10), [animFrom,setAnimFrom]=useState(0), [animTo,setAnimTo]=useState(10)
  const [route,setRoute]=useState('final_storyboard'), [selected,setSelected]=useState(null), [filter,setFilter]=useState('all'), [search,setSearch]=useState('')
  const fileInput=useRef(null), uploadRole=useRef('final')
  async function refresh() { const b=await api('/bootstrap');setBoot(b);return b }
  async function openRun(id) {
    const r=await api('/runs/'+id);setRun(r);setPanelManifest(r.panel_manifest?structuredClone(r.panel_manifest):null);setSelected(null);setFirst(null);setLast(null)
    setRoute(r.prepared.panels.length?'final_storyboard':'final_animatic')
    setKind(r.prepared.panels.length?'storyboard':'animatic')
    const m=r.config.matching||{}
    setPolicy(m.acceptance_mode||'range_top1');setUseText(m.use_text_reranking??true)
    setUseStructure(m.use_structure??true);setTopK(m.top_k??5)
    setMinimum(m.min_visual_similarity??.25);setMargin(m.min_top1_margin??.02)
    return r
  }
  async function attempt(action) { setError('');setNotice('');setBusy(true);try{return await action()}catch(e){setError(e.message)}finally{setBusy(false)} }
  useEffect(()=>{ attempt(async()=>{const b=await refresh();setDraft(b.config);if(b.runs.length)await openRun(b.runs[0].id)}) },[])
  useEffect(()=>{
    if(!job)return
    let cancelled=false
    const poll=async()=>{try{const j=await api('/jobs/'+job);if(cancelled)return;setJobInfo(j);if(j.state!=='running'){setJob(null);if(j.error)setError(j.error);if(j.run_id){await refresh();await openRun(j.run_id);setNotice('Run saved successfully. Your previous results are preserved.')}}}catch(e){if(!cancelled){setError(e.message);setJob(null)}}}
    poll();const timer=setInterval(poll,1200);return()=>{cancelled=true;clearInterval(timer)}
  },[job])
  function start(j){setJob(j.job_id);setJobInfo({state:'running',messages:['Queued for processing…']})}
  const locked=busy||Boolean(job)
  const panels=run?.prepared.panels||[], finals=run?.prepared.frames.final||[], animatic=run?.prepared.frames.animatic||[]
  const rules=run?.config.correspondence_ranges||[], matches=run?.matches||[], decisions=run?.decisions||[]
  const current=finals.find((_,i)=>i+1===selected)||finals[0], finalIndex=selected||1
  const choices=(run?.result?.candidates||[]).filter(c=>c.route===route&&c.final_index===finalIndex).sort((a,b)=>(a.retrieval_rank||a.visual_rank)-(b.retrieval_rank||b.visual_rank))
  const decision=decisions.find(d=>d.route===route&&d.final_index===finalIndex)
  const selectedPair=matches.find(m=>m.route===route&&m.final_index===finalIndex)
  const descriptions=panels.filter(p=>p.text?.description).length
  const visibleFinals=finals.map((f,i)=>({...f,index:i+1})).filter(f=>{
    const d=decisions.find(d=>d.route===route&&d.final_index===f.index)
    return (!search||String(f.index).includes(search))&&(filter==='all'||d?.status===filter)
  })
  const begin=first??panels[0]?.evidence_index, finish=last??begin
  const picked=panels.filter(p=>p.evidence_index>=begin&&p.evidence_index<=finish)
  const heading=nav.find(n=>n.id===page)
  const image=(path,alt,cls='')=>path?<img loading="lazy" className={cls} src={media(run.id,path)} alt={alt}/>:<div className="empty-image"><ImageIcon size={32}/><span>No image available</span></div>
  function fileLabel(role){const p=draft?.[role+'_path'];return p?p.split(/[\\/]/).pop():'No file selected'}
  async function saveRule(removeIndex=null){
    if(!run)return
    const next=removeIndex===null?[...rules,kind==='storyboard'?{evidence_type:kind,panel_indices:picked.map(p=>p.evidence_index),final_start_sec:Number(from),final_end_sec:Number(to)}:{evidence_type:kind,evidence_start_sec:Number(animFrom),evidence_end_sec:Number(animTo),final_start_sec:Number(from),final_end_sec:Number(to)}]:rules.filter((_,i)=>i!==removeIndex)
    const r=await api(`/runs/${run.id}/ranges`,{ranges:next});await refresh();await openRun(r.run_id);setNotice('Correspondence ranges saved.')
  }
  async function runMatching(){const j=await api(`/runs/${run.id}/match`,{acceptance_mode:policy,use_text_reranking:useText,use_structure:useStructure,top_k:Number(topK),min_visual_similarity:Number(minimum),min_top1_margin:Number(margin),text_rank_weight:1.25,text_visual_shortlist:5,text_max_visual_loss:.05});setSettingsOpen(false);start(j)}
  async function review(choice){await api(`/runs/${run.id}/reviews`,{reviews:[{route,final_index:finalIndex,decision:choice?'matched':'unmatched',candidate_id:choice||null,reason:choice?'Selected during optional visual review':'No candidate supports this frame'}]});await openRun(run.id);setRoute(route);setSelected(finalIndex);setNotice('Your correction has been saved.')}
  async function savePanelReview(pages){const response=await api(`/runs/${run.id}/panel-review`,{pages});await openRun(run.id);setPage('ranges');setNotice(`${response.panel_count} reviewed panels saved. Text descriptions were refreshed.`)}
  async function clearGeneratedCache(){const response=await api('/cache/clear',{confirmation:'CLEAR_GENERATED_CACHE'});setCacheOpen(false);setRun(null);setPanelManifest(null);setPage('materials');await refresh();setNotice(`Generated cache cleared: ${response.removed_files} files, ${formatBytes(response.removed_bytes)} removed.`)}

  return <div className="app-shell">
    <aside className="sidebar">
      <div className="brand"><div className="brand-icon"><Layers3 size={22}/></div><div>CS55<span>Evidence Studio</span></div><Badge variant="secondary">BETA</Badge></div>
      <div className="workspace"><span className="workspace-dot"/><div>Production evidence<small>Local workspace</small></div><SlidersHorizontal size={15}/></div>
      <p className="nav-label">WORKSPACE</p>
      <nav>{nav.map(n=><button key={n.id} className={page===n.id?'nav-item active':'nav-item'} onClick={()=>setPage(n.id)}><n.icon size={17}/>{n.name}{n.id==='matches'&&matches.length>0&&<span className="nav-count">{matches.length}</span>}</button>)}</nav>
      <div className="sidebar-divider"/>
      <div className="nav-label flex justify-between">RECENT RUNS <button aria-label="Refresh runs" onClick={()=>attempt(refresh)}><Plus size={14}/></button></div>
      <div className="run-list">{boot?.runs.slice(0,7).map((r,i)=><button key={r.id} className={run?.id===r.id?'run-item selected':'run-item'} onClick={()=>attempt(()=>openRun(r.id))}><span className="run-dot"/><div>{r.id.includes('revision')?'Result revision':`Evidence run ${boot.runs.length-i}`}<small>{new Date(r.created*1000).toLocaleString('en-GB',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</small></div>{r.has_results&&<Check size={13}/>}</button>)}</div>
      <div className="sidebar-bottom"><button className="cache-button" onClick={()=>setCacheOpen(true)} disabled={locked} title="Clear generated cache"><Trash2 size={16}/><div>Clear cache<small>{formatBytes(boot?.cache?.bytes)}</small></div></button><div className="privacy-note"><ShieldCheck size={18}/><div>Private by default<small>Files stay on your device</small></div></div></div>
    </aside>
    <main className="main-shell">
      <header className="topbar"><div className="breadcrumbs">Workspace <ChevronRight size={13}/><span>{heading.name}</span></div><div className="topbar-right"><span className="connection"><i/>Local system</span><a href="https://github.com" target="_blank" rel="noreferrer" aria-label="Open GitHub"><ArrowUpRight size={17}/></a><div className="avatar">CS</div></div></header>
      <div className="page-content">
        <div className="page-heading"><div><div className="eyebrow">PRODUCTION EVIDENCE / {page.toUpperCase()}</div><h1>{page==='matches'?'A clearer picture of your evidence.':heading.name}</h1><p>{page==='matches'?'Compare Final frames with supporting material. Let the system select, and review only when you need to.':page==='panels'?'Check the detected Storyboard regions before they become matching evidence.':page==='ranges'?'Map a scene once. Find the right evidence across the whole sequence.':page==='materials'?'Bring your production materials together in one place.':page==='results'?'Understand what supports the Final, with every decision traceable.':'Inspect the available provenance of each submitted asset.'}</p></div>{page!=='materials'&&<Button onClick={()=>setPage('materials')} variant="outline"><Plus size={15}/>New evaluation</Button>}</div>
        {error&&<div role="alert" className="error-banner"><X size={16}/>{error}<button aria-label="Dismiss error" onClick={()=>setError('')}><X size={14}/></button></div>}
        {notice&&<div role="status" className="notice-banner"><CheckCircle2 size={16}/>{notice}<button aria-label="Dismiss message" onClick={()=>setNotice('')}><X size={14}/></button></div>}
        {job&&<Card className="job-card"><CardContent className="flex items-center gap-4 py-4"><Loader2 className="animate-spin text-primary" size={22}/><div><strong>Processing your evidence</strong><p>{jobInfo?.messages?.at(-1)}</p></div><Badge variant="secondary" className="ml-auto">Running</Badge></CardContent></Card>}

        {page==='materials'&&draft&&<>
          <div className="section-heading"><h2>Source materials</h2><span><span className="required-dot"/>Final + at least one evidence source</span></div>
          <div className="material-grid">{[{role:'final',name:'Final',icon:Film,description:'Your finished film or video',required:true},{role:'storyboard',name:'Storyboard',icon:FileText,description:'A PDF with panels and descriptions'},{role:'animatic',name:'Animatic',icon:Frame,description:'Your intermediate production video'}].map(({role,name,icon:Icon,description,required})=><Card className="material-card" key={role}><CardContent><div className="material-icon"><Icon size={23}/></div><div className="flex items-center justify-between"><h3>{name}</h3><Badge variant="outline">{required?'Required':'Optional'}</Badge></div><p>{description}</p><div className="file-selected"><Icon size={15}/><span title={draft[role+'_path']||''}>{fileLabel(role)}</span>{draft[role+'_path']&&<CheckCircle2 size={15} className="text-emerald-600"/>}</div><Input aria-label={`${name} local path`} placeholder="Enter a local file path…" value={draft[role+'_path']||''} onChange={e=>setDraft({...draft,[role+'_path']:e.target.value})}/><div className="flex gap-2 mt-3"><Button variant="outline" className="flex-1" disabled={locked} onClick={()=>{uploadRole.current=role;fileInput.current.accept=role==='storyboard'?'.pdf':'.mp4,.mov,.mkv,.avi,.webm';fileInput.current.click()}}><UploadCloud size={14}/>Upload</Button>{boot?.native_picker&&<Button variant="outline" disabled={locked} onClick={()=>attempt(async()=>{const r=await api('/choose-file',{});if(r.path)setDraft(d=>({...d,[role+'_path']:r.path}))})}><FolderOpen size={14}/>Browse</Button>}</div></CardContent></Card>)}</div>
          <input hidden ref={fileInput} type="file" onChange={e=>{const file=e.target.files[0],role=uploadRole.current;if(!file)return;attempt(async()=>{const response=await fetch(`/api/upload/${role}?filename=${encodeURIComponent(file.name)}`,{method:'POST',body:file});const data=await response.json();if(!response.ok)throw new Error(data.error||'Upload failed');setDraft(d=>({...d,[role+'_path']:data.path}));setNotice(`${file.name} uploaded.`)});e.target.value=''}}/>
          <Card className="mt-6"><CardHeader><CardTitle className="text-base">Video sampling</CardTitle></CardHeader><CardContent><p className="subtext mb-5">Trim titles and credits, then sample at a consistent interval. Times refer to the original video.</p>{['final','animatic'].map(role=><div className="sampling-row" key={role}><div className="sampling-name"><Film size={16}/>{label(role)}</div>{['start_sec','end_sec','interval_sec'].map(key=><Field key={key} label={key==='start_sec'?'Start · seconds':key==='end_sec'?'End · optional':'Interval · seconds'}><Input aria-label={`${role} ${key}`} type="number" min="0" step=".1" value={draft.sampling?.[role]?.[key]??''} placeholder={key==='end_sec'?'Full duration':''} onChange={e=>setDraft(d=>({...d,sampling:{...d.sampling,[role]:{...d.sampling?.[role],[key]:e.target.value===''?null:Number(e.target.value)}}}))}/></Field>)}</div>)}<div className="bottom-actions"><span><CheckCircle2 size={15}/>Near-black and near-white frames are filtered automatically</span><Button disabled={locked||!draft.final_path||(!draft.storyboard_path&&!draft.animatic_path)} onClick={()=>attempt(async()=>{const j=await api('/prepare',draft);start(j);setPage(draft.storyboard_path?'panels':'ranges')})}>Prepare materials<ArrowRight size={15}/></Button></div></CardContent></Card>
        </>}

        {page!=='materials'&&!run&&!job&&<Card className="empty-state"><Layers3 size={40}/><h2>Your workspace is ready</h2><p>Add your Final and production evidence to start an evaluation.</p><Button onClick={()=>setPage('materials')}>Add materials<ArrowRight size={15}/></Button></Card>}

        {page==='panels'&&run&&<PanelReview run={run} manifest={panelManifest} setManifest={setPanelManifest} locked={locked} onSave={pages=>attempt(()=>savePanelReview(pages))}/>}

        {page==='ranges'&&run&&<>
          <div className="summary-strip"><span><ImageIcon size={16}/><strong>{panels.length}</strong> extracted panels</span><span><FileText size={16}/><strong>{descriptions}</strong> with descriptions</span><span><Link2 size={16}/><strong>{rules.length}</strong> declared ranges</span><Badge variant="secondary" className="ml-auto">Optional panel correction</Badge></div>
          <div className="range-layout"><Card><CardHeader className="flex flex-row items-center justify-between"><CardTitle className="text-base">Build a correspondence range</CardTitle><Badge variant="outline">Scene level</Badge></CardHeader><CardContent>
            <Tabs value={kind} onValueChange={setKind}><TabsList className="w-full mb-6"><TabsTrigger value="storyboard" className="flex-1" disabled={!panels.length}>Storyboard</TabsTrigger><TabsTrigger value="animatic" className="flex-1" disabled={!animatic.length}>Animatic</TabsTrigger></TabsList>
              <TabsContent value="storyboard"><div className="two-fields"><Field label="First panel"><Select value={String(begin??'')} onValueChange={v=>{setFirst(Number(v));if(Number(v)>finish)setLast(Number(v))}}><SelectTrigger><SelectValue placeholder="Choose panel"/></SelectTrigger><SelectContent>{panels.map(p=><SelectItem key={p.evidence_index} value={String(p.evidence_index)}>Panel {p.evidence_index} · page {p.page_index}</SelectItem>)}</SelectContent></Select></Field><Field label="Last panel"><Select value={String(finish??'')} onValueChange={v=>setLast(Number(v))}><SelectTrigger><SelectValue placeholder="Choose panel"/></SelectTrigger><SelectContent>{panels.filter(p=>p.evidence_index>=begin).map(p=><SelectItem key={p.evidence_index} value={String(p.evidence_index)}>Panel {p.evidence_index} · page {p.page_index}</SelectItem>)}</SelectContent></Select></Field></div><div className="panel-endpoints">{[picked[0],picked.at(-1)].map((p,i)=><div key={i}>{p?image(p.panel_path,`Panel ${p.evidence_index}`):<div className="empty-image"/>}<span>{i?'End':'Start'} · Panel {p?.evidence_index||'—'}</span></div>)}</div><div className="inline-info"><Layers3 size={15}/>{picked.length} panels selected as one group</div></TabsContent>
              <TabsContent value="animatic"><div className="two-fields"><Field label="Animatic start · seconds"><Input type="number" min="0" value={animFrom} onChange={e=>setAnimFrom(e.target.value)}/></Field><Field label="Animatic end · seconds"><Input type="number" min="0" value={animTo} onChange={e=>setAnimTo(e.target.value)}/></Field></div><p className="subtext mt-4">All sampled Animatic frames inside this interval will be eligible.</p></TabsContent>
            </Tabs><div className="range-arrow"><Link2 size={16}/><span>Corresponds to this Final interval</span></div><div className="two-fields"><Field label="Final start · seconds"><Input type="number" min="0" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="Final end · seconds"><Input type="number" min="0" value={to} onChange={e=>setTo(e.target.value)}/></Field></div><Button className="w-full mt-6" disabled={locked||(kind==='storyboard'&&!picked.length)} onClick={()=>attempt(()=>saveRule())}><Plus size={15}/>Save range</Button>
          </CardContent></Card><Card><CardHeader><CardTitle className="text-base">Saved correspondence</CardTitle></CardHeader><CardContent>{!rules.length&&<div className="empty-inline"><Link2 size={28}/><p>No baseline yet</p><small>Matching can still run globally, but correspondence conformance cannot be evaluated.</small></div>}{rules.map((r,i)=><div className="saved-range" key={i}><div className="range-number">{String(i+1).padStart(2,'0')}</div><div><strong>{r.evidence_type==='storyboard'?`Panels ${r.panel_indices[0]}–${r.panel_indices.at(-1)}`:`Animatic ${clock(r.evidence_start_sec)}–${clock(r.evidence_end_sec)}`}</strong><small>Final {clock(r.final_start_sec)} → {clock(r.final_end_sec)}</small></div><button aria-label={`Remove range ${i+1}`} className="remove-range" disabled={locked} onClick={()=>attempt(()=>saveRule(i))}><X size={15}/></button></div>)}<div className="soft-note"><CircleHelp size={16}/><p>These declarations are a post-retrieval comparison baseline. They do not restrict which evidence the matcher can retrieve.</p></div></CardContent></Card></div>
          {panels.length>0&&<Card className="mt-6"><CardHeader><CardTitle className="text-base">Panel library <span className="subtext font-normal ml-2">Click a panel to set the start of a range</span></CardTitle></CardHeader><CardContent><div className="panel-library">{panels.map(p=><button key={p.evidence_index} className={p.evidence_index>=begin&&p.evidence_index<=finish?'library-item chosen':'library-item'} onClick={()=>{setFirst(p.evidence_index);setLast(p.evidence_index)}}>{image(p.panel_path,`Storyboard panel ${p.evidence_index}`)}<span>#{p.evidence_index}<small>Page {p.page_index}</small></span></button>)}</div></CardContent></Card>}
        </>}

        {page==='matches'&&run&&<>
          <div className="workspace-toolbar"><div className="toolbar-left"><Badge variant="outline"><CircleDot size={12}/>Final-led global matching</Badge><span className="toolbar-muted">{finals.length} sampled frames</span></div><div className="flex gap-2"><Button variant="outline" onClick={()=>setSettingsOpen(true)} disabled={locked}><Settings2 size={15}/>Settings</Button><Button disabled={locked} onClick={()=>attempt(runMatching)}>{job?<Loader2 className="animate-spin" size={15}/>:<Play size={14}/>}Run matching</Button></div></div>
          {run.prepared.assets.storyboard&&!run.prepared.panel_review_confirmed&&<div className="error-banner"><ImageIcon size={16}/>Storyboard panels have not been confirmed.<Button size="sm" variant="outline" className="ml-auto" onClick={()=>setPage('panels')}>Review panels</Button></div>}
          {!rules.length&&<div className="soft-note mb-5"><Link2 size={17}/><p>Matching searches all extracted evidence. Add correspondence only if you want conformance diagnostics.</p><Button size="sm" variant="outline" className="ml-auto" onClick={()=>setPage('ranges')}>Add baseline<ArrowRight size={14}/></Button></div>}
          <div className="matching-layout"><Card className="frame-browser"><div className="browser-heading"><h3>Final frames</h3><Badge variant="secondary">{finals.length}</Badge></div><div className="browser-filters"><div className="search-input"><Search size={14}/><Input aria-label="Find frame" placeholder="Find a frame…" value={search} onChange={e=>setSearch(e.target.value)}/></div><Select value={filter} onValueChange={setFilter}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{['all','provisionally_matched','requires_review','insufficient_evidence','human_confirmed','not_evaluated'].map(v=><SelectItem key={v} value={v}>{v==='all'?'All frames':label(v)}</SelectItem>)}</SelectContent></Select></div><div className="frame-list">{visibleFinals.map(f=>{const state=decisions.find(d=>d.route===route&&d.final_index===f.index)?.status;return <button key={f.index} className={f.index===finalIndex?'frame-item selected':'frame-item'} onClick={()=>setSelected(f.index)}>{image(f.keyframe_path,`Final frame ${f.index}`)}<div><strong>Frame {String(f.index).padStart(3,'0')}</strong><small>{clock(f.timestamp_sec)}</small></div><span className={['provisionally_matched','human_confirmed'].includes(state)?'frame-state good':'frame-state'}/></button>})}</div></Card>
            <div className="comparison-column"><Card className="final-card"><div className="image-heading"><div><Badge variant="secondary">FINAL</Badge><strong>Frame {String(finalIndex).padStart(3,'0')}</strong><span>{clock(current?.timestamp_sec)}</span></div><StateBadge value={decision?.status}/></div><div className="final-preview">{image(current?.keyframe_path,`Final frame ${finalIndex}`)}</div><div className="image-footer"><span><Film size={14}/>Original video sample</span><span>{run.prepared.assets.final?.split('/').pop()}</span></div></Card>
              <div className="candidates-heading"><div><h2>Supporting evidence <Badge variant="secondary">{choices.length}</Badge></h2><p>{selectedPair?'The selected global correspondence is saved. You can optionally correct it below.':'Candidates are ranked across all extracted evidence, then compared with your declared baseline.'}</p></div><Tabs value={route} onValueChange={setRoute}><TabsList><TabsTrigger value="final_storyboard" disabled={!panels.length}>Storyboard</TabsTrigger><TabsTrigger value="final_animatic" disabled={!animatic.length}>Animatic</TabsTrigger></TabsList></Tabs></div>
              {!choices.length?<Card className="empty-candidates"><Search size={25}/><h3>{run.result?'No candidate for this route':'Ready when you are'}</h3><p>{decision?.reason?label(decision.reason):'Run matching to find evidence inside your declared ranges.'}</p></Card>:<div className="candidate-grid">{choices.map((c,i)=>{const chosen=selectedPair?.id===c.id;return <Card key={c.id} className={chosen?'candidate-card chosen':'candidate-card'}><div className="candidate-img">{image(c.evidence_path,`Evidence ${c.evidence_index}`)}<Badge className="candidate-rank" variant={chosen?'default':'secondary'}>{chosen?<Check size={11}/>:null}{chosen?'Selected':`Candidate ${i+1}`}</Badge></div><CardContent><div className="flex items-center justify-between"><h3>{route==='final_storyboard'?'Panel':'Animatic frame'} {c.evidence_index}</h3><span className="score-value"><Explain text="Cosine similarity between CLIP image embeddings. Higher values indicate greater feature similarity; this is not a probability or the Visual support coverage score.">{c.visual_similarity.toFixed(3)}</Explain></span></div><p className="candidate-description">{c.description||'No associated text description.'}</p><div className="candidate-tags"><span>Visual #{c.visual_rank}</span>{c.text_group_rank&&<span><Sparkles size={11}/>Text #{c.text_group_rank}</span>}{c.text_reranking_applied&&<span className="semantic-tag">Text reranked</span>}</div><Button size="sm" variant={chosen?'secondary':'outline'} className="w-full mt-4" disabled={locked} onClick={()=>attempt(()=>review(c.id))}>{chosen?<><CheckCheck size={14}/>Confirm selection</>:<>Use this candidate<ArrowUpRight size={13}/></>}</Button></CardContent></Card>})}</div>}
              {choices.length>0&&<div className="review-footer"><span><CircleHelp size={15}/>Human review is optional in Range Top-1 mode.</span><Button variant="ghost" size="sm" disabled={locked} onClick={()=>attempt(()=>review(null))}>None of these match</Button></div>}
            </div></div>
        </>}

        {page==='results'&&run&&<>
          <div className="assessment-grid">{[{title:'Supported Final frames',value:run.scores?.provisional_and_human?.supported_final_frames??'—',note:`of ${finals.length} retained samples`,icon:CheckCircle2},{title:'Visual support',value:run.scores?.provisional_and_human?.visual_support_score!=null?`${run.scores.provisional_and_human.visual_support_score}%`:'—',note:'Automatic + human selections',icon:ScanLine},{title:'Sequence consistency',value:run.scores?.provisional_and_human?.sequence_consistency_score!=null?`${run.scores.provisional_and_human.sequence_consistency_score}%`:'—',note:'Comparable evidence index pairs',icon:Layers3}].map(m=><Card key={m.title}><CardContent><div className="metric-title"><MetricLabel>{m.title}</MetricLabel><m.icon size={17}/></div><strong className="metric-value"><Explain text={assessmentReason(m.title,run.scores?.provisional_and_human)}>{m.value}</Explain></strong><small>{m.note}</small></CardContent></Card>)}</div>
          <Card className="mt-6"><CardHeader><CardTitle className="text-base">Sequence by route</CardTitle></CardHeader><CardContent><div className="table-wrap"><table><thead><tr><th><MetricLabel>Relationship</MetricLabel></th><th><MetricLabel>Selected pairs</MetricLabel></th><th><MetricLabel>Concordant</MetricLabel></th><th><MetricLabel>Discordant</MetricLabel></th><th><MetricLabel>Ties</MetricLabel></th><th><MetricLabel>Score</MetricLabel></th></tr></thead><tbody>{(run.scores?.provisional_and_human?.route_order||[]).map(r=><tr key={r.route}><td>{label(r.route)}</td><td>{r.confirmed_pair_count}</td><td>{r.concordant_pair_count}</td><td>{r.discordant_pair_count}</td><td>{r.tied_pair_count}</td><td><Explain text={sequenceReason(r)}>{r.score==null?'N/A':r.score+'%'}</Explain></td></tr>)}</tbody></table></div><p className="subtext mt-4">Automatic selections remain provisional. These metrics describe support and ordering, rather than retrieval accuracy.</p></CardContent></Card>
          {run.correspondence?.provisional_and_human&&<Card className="mt-6"><CardHeader><CardTitle className="text-base">Correspondence conformance</CardTitle></CardHeader><CardContent><div className="assessment-grid timestamp-metrics"><div><span className="metric-title"><MetricLabel>Conformance score</MetricLabel></span><strong><Explain text={`${metricHelp['Conformance score']} Current result: ${run.correspondence.provisional_and_human.conforming_final_route_count} / ${run.correspondence.provisional_and_human.evaluable_final_route_count} × 100.`}>{run.correspondence.provisional_and_human.correspondence_conformance_score==null?'N/A':`${run.correspondence.provisional_and_human.correspondence_conformance_score}%`}</Explain></strong></div><div><span className="metric-title"><MetricLabel>Evaluable Final routes</MetricLabel></span><strong>{run.correspondence.provisional_and_human.evaluable_final_route_count}</strong></div><div><span className="metric-title"><MetricLabel>Conforming pairs</MetricLabel></span><strong>{run.correspondence.provisional_and_human.conforming_final_route_count}</strong></div></div><div className="table-wrap mt-4"><table><thead><tr><th><MetricLabel>Route</MetricLabel></th><th><MetricLabel>Conforming</MetricLabel></th><th><MetricLabel>Outside baseline</MetricLabel></th><th><MetricLabel>Expected not observed</MetricLabel></th><th><MetricLabel>Undeclared</MetricLabel></th><th><MetricLabel>Expected evidence coverage</MetricLabel></th></tr></thead><tbody>{run.correspondence.provisional_and_human.route_summaries.map(r=><tr key={r.route}><td>{label(r.route)}</td><td><Explain text={`${metricHelp.Conforming} ${r.conforming_final_count} / ${r.evaluable_final_count} × 100 = ${r.correspondence_conformance_score??'N/A'}%.`}>{r.conforming_final_count}/{r.evaluable_final_count}</Explain></td><td>{r.outside_declared_count}</td><td>{r.expected_support_not_observed_count}</td><td>{r.undeclared_final_count}</td><td><Explain text={`${metricHelp['Expected evidence coverage']} Current result: ${r.observed_declared_evidence_count} / ${r.declared_evidence_count} × 100.`}>{r.expected_evidence_coverage_score==null?'N/A':`${r.expected_evidence_coverage_score}%`}</Explain></td></tr>)}</tbody></table></div><p className="subtext mt-4">Global retrieval is compared with submitter-declared correspondence after matching. Deviation means disagreement with the declaration, not proven retrieval error.</p></CardContent></Card>}
          <Card className="mt-6"><CardHeader><CardTitle className="text-base">Native outputs</CardTitle></CardHeader><CardContent><div className="export-grid">{run.files.map(name=><a className="export-item" key={name} href={`/api/runs/${run.id}/download/${name}`} download><FileText size={18}/><div>{name}<small>JSON · Native system output</small></div><Download size={15}/></a>)}</div></CardContent></Card>
        </>}

        {page==='provenance'&&run&&<>
          <div className="workspace-toolbar"><p className="subtext">Four independent provenance indicators plus a separate timestamp evidence score.</p><Button disabled={locked} onClick={()=>attempt(async()=>start(await api(`/runs/${run.id}/provenance`,{})))}><ShieldCheck size={15}/>Inspect provenance</Button></div>
          {!run.provenance?<Card className="empty-state"><ShieldCheck size={38}/><h2>Provenance evidence</h2><p>Inspect file identity, C2PA, source-project evidence, editing transparency and timestamp chronology.</p></Card>:Object.entries(run.provenance.assets).map(([name,asset])=><Card className="mb-5" key={name}><CardHeader><CardTitle className="capitalize text-base">{name}</CardTitle></CardHeader><CardContent><div className="provenance-grid">{Object.entries(asset.indicator_scores).map(([key,s])=><div className="provenance-metric" key={key}><span><Explain text={provenanceReason(s)}>{s.label}</Explain></span><strong><Explain text={provenanceReason(s)}>{s.score??'N/A'}<small>/100</small></Explain></strong><p>{s.reason}</p><Dialog><DialogTrigger asChild><Button size="sm" variant="ghost">View checks<ArrowUpRight size={13}/></Button></DialogTrigger><DialogContent className="max-w-2xl"><DialogHeader><DialogTitle>{s.label}</DialogTitle><DialogDescription>{s.reason}</DialogDescription></DialogHeader><div className="table-wrap"><table><thead><tr><th><MetricLabel>Check</MetricLabel></th><th><MetricLabel>Satisfied</MetricLabel></th><th><MetricLabel>Points</MetricLabel></th></tr></thead><tbody>{s.components.map(c=><tr key={c.check}><td><Explain text={c.explanation||`Condition: ${label(c.check)}. Source: ${c.source||'unavailable'}. Observed: ${JSON.stringify(c.observed_value??null)}`}>{label(c.check)}</Explain></td><td>{c.passed?'Yes':'No'}</td><td><Explain text={`${c.passed?'Condition satisfied':'Condition not satisfied'}: ${c.points_awarded} of ${c.maximum_points} points. ${c.explanation||''} ${s.gate_reason||''}`}>{c.points_awarded}/{c.maximum_points}</Explain></td></tr>)}</tbody></table></div>{s.gate_reason&&<p className="subtext">{s.gate_reason}</p>}</DialogContent></Dialog></div>)}</div></CardContent></Card>)}
          {run.timestamps?.method==='weighted_timestamp_evidence_v2'&&<Card className="mb-5"><CardHeader><CardTitle className="text-base">Project timestamp evidence</CardTitle></CardHeader><CardContent><div className="assessment-grid timestamp-metrics"><div><Explain text="The average of all available Storyboard-to-Final and Animatic-to-Final timestamp scores. Each relationship remains visible below.">Project score</Explain><strong className="metric-value"><Explain text="Arithmetic mean of available relationship timestamp scores. Relationships without a score are excluded; if none are available the result is N/A.">{run.timestamps.project_timestamp_score??'N/A'}{run.timestamps.project_timestamp_score!=null&&<small>/100</small>}</Explain></strong></div><div><Explain text="A plain-language band derived from the project score: strong, moderate, limited, weak/conflicting, or unavailable.">Status</Explain><strong className="capitalize">{label(run.timestamps.project_status)}</strong></div><div><Explain text="Checks whether available creation times follow Storyboard → Animatic → Final and whether all three were generated in an unusually short interval.">Production chain</Explain><strong className="capitalize">{label(run.timestamps.production_chain_analysis?.status||'not applicable')}</strong></div></div>{run.timestamps.production_chain_analysis?.reason&&<p className="subtext mt-4">{run.timestamps.production_chain_analysis.reason}</p>}<p className="subtext mt-4">This score measures timestamp availability and chronological support. It is not an authenticity probability.</p></CardContent></Card>}
          {run.timestamps?.relationships?.map(r=><TimestampRelationshipCard key={r.relationship} relationship={r} modern={run.timestamps.method==='weighted_timestamp_evidence_v2'}/>)}
        </>}
        <footer className="page-footer"><span><Layers3 size={13}/>CS55 Evidence Studio</span><span>Evidence support. Transparent decisions.</span></footer>
      </div>
    </main>
    <Dialog open={settingsOpen} onOpenChange={setSettingsOpen}><DialogContent><DialogHeader><DialogTitle>Matching settings</DialogTitle><DialogDescription>Fine-tune global candidate selection without extracting your materials again.</DialogDescription></DialogHeader><Field label="Selection policy"><Select value={policy} onValueChange={setPolicy}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="range_top1">Global Top-1 · Automatic</SelectItem><SelectItem value="strict">Strict support checks</SelectItem></SelectContent></Select></Field><div className="two-fields"><Field label="Candidates per frame"><Input type="number" min="1" max="50" value={topK} onChange={e=>setTopK(e.target.value)}/></Field><Field label="Minimum visual similarity"><Input type="number" min="0" max="1" step=".01" value={minimum} onChange={e=>setMinimum(e.target.value)}/></Field></div>{policy==='strict'&&<Field label="Minimum Top-1 / Top-2 margin"><Input type="number" min="0" step=".01" value={margin} onChange={e=>setMargin(e.target.value)}/></Field>}<div className="switch-row"><div><strong>Text semantics</strong><p>Rerank visually similar panels using descriptions.</p></div><Switch checked={useText} onCheckedChange={setUseText} aria-label="Text semantics"/></div><div className="switch-row"><div><strong>Local structure</strong><p>Record directional edge and spatial support.</p></div><Switch checked={useStructure} onCheckedChange={setUseStructure} aria-label="Local structure"/></div><p className="subtext">Correspondence declarations are compared after retrieval and never restrict the candidate search.</p><Button disabled={locked||!run} onClick={()=>attempt(runMatching)}><Play size={14}/>Run with these settings</Button></DialogContent></Dialog>
    <Dialog open={cacheOpen} onOpenChange={setCacheOpen}><DialogContent><DialogHeader><DialogTitle>Clear generated cache?</DialogTitle><DialogDescription>This removes generated runs, sampled frames, extracted panels, uploaded copies and JSON results from this local workspace. Source files referenced by local paths, code, dependencies and model downloads are not removed.</DialogDescription></DialogHeader><div className="cache-summary"><Trash2 size={20}/><div><strong>{formatBytes(boot?.cache?.bytes)}</strong><span>{boot?.cache?.files||0} generated files · {boot?.cache?.entries||0} workspace entries</span></div></div><div className="soft-note"><Info size={16}/><p>This cannot be undone. Download any JSON results you need before clearing the cache.</p></div><div className="dialog-actions"><Button variant="outline" onClick={()=>setCacheOpen(false)}>Cancel</Button><Button variant="destructive" disabled={locked} onClick={()=>attempt(clearGeneratedCache)}><Trash2 size={14}/>Clear generated cache</Button></div></DialogContent></Dialog>
  </div>
}

createRoot(document.getElementById('root')).render(<TooltipProvider><App/></TooltipProvider>)
